use std :: io :: { IsTerminal , Read } ; use std :: panic ; use std :: path :: PathBuf ; use anyhow :: { Context , Result } ; use clap :: Parser ; use forge_api :: ForgeAPI ; use forge_config :: ForgeConfig ; use forge_domain :: TitleFormat ; use forge_main :: { Cli , Sandbox , TitleDisplayExt , TopLevelCommand , UI , tracker } ; use windows_sys :: Win32 :: System :: Console :: { ENABLE_VIRTUAL_TERMINAL_PROCESSING , GetConsoleMode , GetStdHandle , STD_OUTPUT_HANDLE , SetConsoleMode , } ; use forge_main :: TopLevelCommand ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Enables ENABLE_VIRTUAL_TERMINAL_PROCESSING on the stdout console handle."] # [doc = ""] # [doc = " The `enable_ansi_support` crate sets VT processing on the `CONOUT$` handle,"] # [doc = " but console mode flags are **per-handle** on Windows. The `CONOUT$` flag may"] # [doc = " not propagate to the individual `STD_OUTPUT_HANDLE` handle on all Windows"] # [doc = " configurations (e.g. older builds, cmd.exe launched in certain ways, or"] # [doc = " when handles have been duplicated)."] # [doc = ""] # [doc = " Without VT processing on stdout, ANSI escape codes from forge's markdown"] # [doc = " renderer (bold, colors, inline code styling) are displayed as raw text"] # [doc = " like `←[33m` instead of being interpreted as formatting."] # [doc = ""] # [doc = " We intentionally do NOT set VT processing on stderr. The `console` crate"] # [doc = " (used by `indicatif`) uses `GetConsoleMode` to detect VT support and"] # [doc = " switches between Win32 Console APIs and ANSI escapes accordingly. The"] # [doc = " Win32 Console API path (`FillConsoleOutputCharacterA` /"] # [doc = " `SetConsoleCursorPosition`) modifies the screen buffer in-place, which"] # [doc = " produces clean scrollback when clearing spinner lines. Enabling VT"] # [doc = " processing on stderr would cause `console` to use ANSI escapes instead,"] # [doc = " leaving spinner artifacts in the terminal scrollback buffer."] # [cfg (windows)] fn enable_stdout_vt_processing () { use windows_sys :: Win32 :: System :: Console :: { ENABLE_VIRTUAL_TERMINAL_PROCESSING , GetConsoleMode , GetStdHandle , STD_OUTPUT_HANDLE , SetConsoleMode , } ; unsafe { let handle = GetStdHandle (STD_OUTPUT_HANDLE) ; let mut mode = 0 ; if GetConsoleMode (handle , & mut mode) != 0 { let _ = SetConsoleMode (handle , mode | ENABLE_VIRTUAL_TERMINAL_PROCESSING) ; } } }